INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenbanken > Begriffe
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Bezeichnet Redundanz in Datenbanken die unnötige Wiederholung von Daten?', 2, '[{"text": "Ja", "correct": true, "because": "Redundanz ist doppelte Datenspeicherung"}, {"text": "Nein", "correct": false, "because": "Definition von Redundanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine 1:1-Kardinalität in Datenbanken eine Beziehung, bei der ein Datensatz genau einem anderen Datensatz zugeordnet ist?', 2, '[{"text": "Ja", "correct": true, "because": "1:1 bedeutet eine eindeutige Zuordnung"}, {"text": "Nein", "correct": false, "because": "Definition von 1:1"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Primärschlüssel in einer Datenbank NULL-Werte enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Primärschlüssel muss eindeutig und nicht NULL sein"}, {"text": "Ja", "correct": false, "because": "NULL verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Stellt referentielle Integrität sicher, dass Fremdschlüsselwerte immer auf existierende Primärschlüssel verweisen?', 2, '[{"text": "Ja", "correct": true, "because": "Referentielle Integrität sichert Verknüpfungen"}, {"text": "Nein", "correct": false, "because": "Kernprinzip der Integrität"}]'),
('00000000-0000-0000-0000-000000000000', 'Bedeutet eine m:n-Kardinalität, dass mehrere Datensätze einer Tabelle mit mehreren Datensätzen einer anderen Tabelle verknüpft sein können?', 2, '[{"text": "Ja", "correct": true, "because": "m:n beschreibt viele-zu-viele-Beziehungen"}, {"text": "Nein", "correct": false, "because": "Definition von m:n"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was beschreibt Redundanz in einer Datenbank?', 2, '[{"text": "Unnötige Datenwiederholung", "correct": true, "because": "Redundanz führt zu Duplikaten"}, {"text": "Eindeutige Datensätze", "correct": false, "because": "Gegenteil von Redundanz"}, {"text": "Datenintegrität", "correct": false, "because": "Anderer Begriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kardinalität beschreibt eine Beziehung, bei der ein Datensatz einer Tabelle mehreren Datensätzen einer anderen Tabelle zugeordnet ist?', 3, '[{"text": "1:n", "correct": true, "because": "Ein-zu-viele-Beziehung"}, {"text": "1:1", "correct": false, "because": "Ein-zu-ein"}, {"text": "m:n", "correct": false, "because": "Viele-zu-viele"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schlüssel dient in einer Datenbank dazu, Datensätze eindeutig zu identifizieren?', 2, '[{"text": "Primärschlüssel", "correct": true, "because": "Eindeutige Identifikation"}, {"text": "Fremdschlüssel", "correct": false, "because": "Verknüpfung"}, {"text": "Kandidatenschlüssel", "correct": false, "because": "Mögliche, aber nicht Primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Begriff beschreibt die Regel, dass Fremdschlüsselwerte mit existierenden Primärschlüsselwerten übereinstimmen müssen?', 2, '[{"text": "Referentielle Integrität", "correct": true, "because": "Sichert Datenkonsistenz"}, {"text": "Redundanz", "correct": false, "because": "Datenwiederholung"}, {"text": "Kardinalität", "correct": false, "because": "Beziehungsverhältnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kardinalität erfordert in der Regel eine zusätzliche Verknüpfungstabelle?', 2, '[{"text": "m:n", "correct": true, "because": "Viele-zu-viele braucht Verknüpfung"}, {"text": "1:1", "correct": false, "because": "Direkte Zuordnung"}, {"text": "1:n", "correct": false, "because": "Fremdschlüssel reicht"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Begriffe gehören zur Datenbankmodellierung?', 4, '[{"text": "Redundanz", "correct": true, "because": "Datenwiederholung"}, {"text": "Kardinalitäten", "correct": true, "because": "Beziehungsverhältnisse"}, {"text": "Schlüssel", "correct": true, "because": "Identifikation und Verknüpfung"}, {"text": "Datenrate", "correct": false, "because": "Kein Modellierungsbegriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kardinalitäten gibt es in relationalen Datenbanken?', 3, '[{"text": "1:1", "correct": true, "because": "Ein-zu-ein"}, {"text": "1:n", "correct": true, "because": "Ein-zu-viele"}, {"text": "m:n", "correct": true, "because": "Viele-zu-viele"}, {"text": "n:n", "correct": false, "because": "Ungültige Schreibweise"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein Primärschlüssel?', 4, '[{"text": "Eindeutigkeit", "correct": true, "because": "Keine Duplikate"}, {"text": "Nicht-NULL", "correct": true, "because": "NULL verboten"}, {"text": "Identifikation", "correct": true, "because": "Eindeutige Zuordnung"}, {"text": "Mehrere Spalten", "correct": false, "because": "Möglich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben erfüllt die referentielle Integrität?', 3, '[{"text": "Fremdschlüssel verweisen auf Primärschlüssel", "correct": true, "because": "Kernfunktion"}, {"text": "Konsistenz zwischen Tabellen", "correct": true, "because": "Datenintegrität"}, {"text": "Verhinderung ungültiger Einträge", "correct": true, "because": "Sicherstellung"}, {"text": "Datenredundanz erhöhen", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme kann Redundanz in Datenbanken verursachen?', 3, '[{"text": "Einfügeanomalien", "correct": true, "because": "Dateninkonsistenz beim Hinzufügen"}, {"text": "Änderungsanomalien", "correct": true, "because": "Inkonsistenz bei Änderungen"}, {"text": "Löschanomalien", "correct": true, "because": "Datenverlust beim Löschen"}, {"text": "Schnellere Abfragen", "correct": false, "because": "Kein Vorteil"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Redundanz führt zu Datenwiederholung. b) Sie verbessert immer die Datenintegrität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wiederholung ja, Integrität nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine 1:n-Kardinalität erfordert einen Fremdschlüssel. b) Eine 1:1-Kardinalität braucht eine Verknüpfungstabelle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fremdschlüssel ja, Verknüpfung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Primärschlüssel sind immer eindeutig. b) Fremdschlüssel können NULL enthalten.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Eindeutig ja, NULL möglich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Referentielle Integrität verhindert ungültige Fremdschlüsselwerte. b) Sie erfordert Redundanz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Integrität ja, Redundanz nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine m:n-Kardinalität benötigt eine Verknüpfungstabelle. b) Redundanz vermeidet Löschanomalien.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verknüpfung ja, Redundanz nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

